<?php require_once 'config/config.php'; $q=trim($_GET['q']??''); $cats=db()->query("SELECT * FROM freelancer_categories ORDER BY name")->fetchAll(); $sql="SELECT f.*,fc.name category FROM freelancers f JOIN freelancer_categories fc ON fc.id=f.category_id WHERE f.status='active'";$params=[];if($q){$sql.=" AND (f.name LIKE ? OR f.bio LIKE ? OR fc.name LIKE ?)";$params=["%$q%","%$q%","%$q%"];} $sql.=" ORDER BY f.featured DESC,f.id DESC";$st=db()->prepare($sql);$st->execute($params);$people=$st->fetchAll();$pageTitle='Freelancers';require 'includes/header.php'; ?>
<section class="page-hero"><div class="container"><div class="eyebrow">Local talent network</div><h1>Ideas need<br><span style="color:var(--teal)">good people.</span></h1><p>Meet the designers, developers, writers, and marketers helping Quetta’s ideas move forward.</p></div></section><section class="section"><div class="container"><form class="filter-bar"><input class="input" name="q" value="<?=e($q)?>" placeholder="Search by name or skill"><button class="btn btn-primary">Search talent</button></form><div class="cards"><?php foreach($people as $person): ?><article class="card"><div class="card-body"><div class="profile"><img class="profile-img" src="<?=image_url($person['image'])?>" alt="<?=e($person['name'])?>"><div><h3><?=e($person['name'])?></h3><span class="kicker"><?=e($person['category'])?></span></div></div><p><?=e($person['bio'])?></p><p class="card-meta"><?=e($person['experience'])?> experience · <?=e($person['location'])?></p><a class="btn btn-secondary" style="margin-top:17px;width:100%;justify-content:center" href="contact.php?type=freelancer&subject=<?=urlencode($person['name'])?>">Contact <?=e(explode(' ',$person['name'])[0])?> ↗</a></div></article><?php endforeach; ?></div></div></section><?php require 'includes/footer.php'; ?>